css:
[data-bz-section="info-cards"] .bz-block { padding-block: 0; }
[data-bz-section="info-cards"] [data-bz-node="ic-intro"] p { max-width: 62ch; color: #3b3a37; margin-bottom: 0; }
[data-bz-section="info-cards"] .bz-row[data-bz-node="ic-grid"] { display: grid; grid-template-columns: repeat(var(--ic-cols, 3), minmax(0, 1fr)); gap: 12px; margin-top: 28px; }
[data-bz-section="info-cards"] .bz-col[data-bz-node^="ic-card"] { grid-column: auto; background: var(--card); border: 1px solid var(--line); border-radius: var(--radius-card); padding: 24px 22px 26px; }
[data-bz-section="info-cards"] .bz-block[data-bz-node^="ic-title"] .bz-eyebrow { font-size: 10.5px; color: var(--muted); margin: 0 0 6px; }
[data-bz-section="info-cards"] .bz-block[data-bz-node^="ic-title"] h3 { font-size: 15px; line-height: 1.3; margin: 0 0 12px; }
[data-bz-section="info-cards"] .bz-block[data-bz-node^="ic-text"] p { font-size: 14px; line-height: 1.6; color: #4a4945; margin: 0; }
[data-bz-section="info-cards"] .bz-block[data-bz-node^="ic-link"] p { margin: 14px 0 0; }
[data-bz-section="info-cards"] .bz-block[data-bz-node^="ic-link"] a { font: 700 12px / 1.4 var(--font-body); letter-spacing: .08em; text-transform: uppercase; color: var(--ink); text-decoration: none; }
[data-bz-section="info-cards"] .bz-block[data-bz-node^="ic-link"] a:empty { display: none; }
@media (max-width: 1100px) { [data-bz-section="info-cards"] .bz-row[data-bz-node="ic-grid"] { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 640px) { [data-bz-section="info-cards"] .bz-row[data-bz-node="ic-grid"] { grid-template-columns: minmax(0, 1fr); } }
